/**
 * Seed script for library_items table.
 * Inserts ~551 botanically-accurate plant and hardscape items.
 *
 * Usage:  npx tsx scripts/seed-library-data.ts
 *
 * Requires: NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY
 * (reads from .env.local when present)
 */

import { createClient } from "@supabase/supabase-js";
import * as fs from "fs";
import * as path from "path";

/* ------------------------------------------------------------------ */
/* Env                                                                 */
/* ------------------------------------------------------------------ */
const envPath = path.resolve(process.cwd(), ".env.local");
if (fs.existsSync(envPath)) {
  for (const line of fs.readFileSync(envPath, "utf-8").split("\n")) {
    const t = line.trim();
    if (!t || t.startsWith("#")) continue;
    const eq = t.indexOf("=");
    if (eq === -1) continue;
    const k = t.slice(0, eq).trim();
    const v = t.slice(eq + 1).trim().replace(/^["']|["']$/g, "");
    if (!process.env[k]) process.env[k] = v;
  }
  console.log("Loaded .env.local");
} else {
  console.log(".env.local not found — using existing env vars");
}

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!SUPABASE_URL || !SERVICE_KEY) {
  console.error("Missing NEXT_PUBLIC_SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY");
  process.exit(1);
}
const supabase = createClient(SUPABASE_URL, SERVICE_KEY);

/* ------------------------------------------------------------------ */
/* Shorthand types & builders                                          */
/* ------------------------------------------------------------------ */
type P = {
  cn: string; sn: string; cat: string; sub: string; desc: string;
  zn: string; zx: string; hmin: number; hmax: number; smin: number; smax: number;
  sun: string; water: string; gr: string; ml: string; ft: string;
  bs?: string[]; fc?: string[]; flc?: string[];
  dt?: boolean; dr?: boolean; ap?: boolean; nr?: string[]; tp?: boolean;
  ds: string[]; cu: string[];
};
type H = {
  cn: string; sub: string; desc: string;
  mt: string; co: string[];
  ds: string[]; cu: string[];
  hmin?: number; hmax?: number; smin?: number; smax?: number;
};

function p(d: P) {
  return {
    item_type: "plant" as const,
    common_name: d.cn, scientific_name: d.sn, category: d.cat, subcategory: d.sub,
    description: d.desc, zone_min: d.zn, zone_max: d.zx,
    height_min_ft: d.hmin, height_max_ft: d.hmax,
    spread_min_ft: d.smin, spread_max_ft: d.smax,
    sun_requirement: d.sun, water_needs: d.water, growth_rate: d.gr,
    maintenance_level: d.ml, foliage_type: d.ft,
    bloom_season: d.bs ?? null, flower_colors: d.fc ?? null,
    foliage_colors: d.flc ?? ["green"],
    drought_tolerant: d.dt ?? false, deer_resistant: d.dr ?? false,
    attracts_pollinators: d.ap ?? false, native_regions: d.nr ?? null,
    toxic_to_pets: d.tp ?? false,
    material_type: null, color_options: null,
    design_styles: d.ds, common_uses: d.cu,
  };
}

function h(d: H) {
  return {
    item_type: "hardscape" as const,
    common_name: d.cn, scientific_name: null,
    category: "Hardscape", subcategory: d.sub,
    description: d.desc,
    zone_min: null, zone_max: null,
    height_min_ft: d.hmin ?? null, height_max_ft: d.hmax ?? null,
    spread_min_ft: d.smin ?? null, spread_max_ft: d.smax ?? null,
    sun_requirement: null, water_needs: null, growth_rate: null,
    maintenance_level: null, foliage_type: null,
    bloom_season: null, flower_colors: null, foliage_colors: null,
    drought_tolerant: false, deer_resistant: false, attracts_pollinators: false,
    native_regions: null, toxic_to_pets: false,
    material_type: d.mt, color_options: d.co,
    design_styles: d.ds, common_uses: d.cu,
  };
}

